import uploadPictures from "@/components/uploadPictures";
import build from "./build";
export default {
    name: "diyTabelBuild",
    components: {
        uploadPictures
    },
    mixins: [build],
    watch: {
        valueModel: {
            handler(n) {
                this.changeValue();
            },
            deep: true
        },
    },
    data(){
        return {
            gridPic: {
                xl: 6,
                lg: 8,
                md: 12,
                sm: 12,
                xs: 12,
            },
            gridBtn: {
                xl: 4,
                lg: 8,
                md: 8,
                sm: 8,
                xs: 8,
            },
            data: [],
            modalPic:false,
            isChoice:'单选',
            tableIndex:0,
            keyName:'icon'
        };
    },
    mounted() {

    },
    methods: {
        // 点击商品图
        modalPicTap(item,index) {
            this.modalPic = true;
            this.tableIndex = index;
            this.keyName = item.key;
        },
        // 获取单张图片信息
        getPic(pc) {
            this.valueModel[this.tableIndex][this.keyName] = pc.att_dir;
            this.modalPic = false;
        },
        add() {
            let value = {};
            this.options.map(item => {
                if (item.key === 'sort') {
                    value[item.key] = 0;
                } else {
                    value[item.key] = '';
                }
            })
            this.valueModel.push(value);
        },
        del(index) {
            this.valueModel.splice(index,1);
        },
        changeValue() {
            this.$emit('changeValue', {field: this.field,value: this.valueModel});
            //触发change事件
            this.on['change'] && this.on['change'](this.valueModel);
        },
    },
    computed: {
        columns(){
            let columns = [];
            this.options.map(item => {
                columns.push({title:item.name,slot:item.key,align:item.alert || 'left'});
            });
            columns.push({title:'操作', slot:'action', width:100, align:'left'});
            return columns;
        },
    }
}
